exec_args:
set -e
mkdir -p .kronn
cat > /tmp/pulls.json
python3 -c "
import json
raw=json.load(open('/tmp/pulls.json'))
SKIP='skip-auto-review'
prs={}
stack=[raw]
while stack:
    x=stack.pop()
    if isinstance(x,list):
        stack.extend(x); continue
    if isinstance(x,dict):
        b=x.get('base')
        if 'number' in x and isinstance(b,dict):
            labels={(l.get('name') or '').lower() for l in (x.get('labels') or [])}
            repo=((b.get('repo') or {})).get('full_name','')
            num=x.get('number')
            author=(x.get('user') or {}).get('login','')
            head=(x.get('head') or {}).get('sha','')
            if (not x.get('draft')) and (SKIP not in labels) and (not author.endswith('[bot]')) and repo and num is not None:
                prs[(repo,num)]={'number':num,'baseRef':b.get('ref','main'),'author':author,'repo':repo,'head':head}
        else:
            stack.extend(x.values())
out=sorted(prs.values(), key=lambda d:(d['repo'],-d['number']))
json.dump(out, open('.kronn/prs_candidates.json','w'))
print(json.dumps(out))
"
